@Composable
fun SellTicketScreen(
    openDraws: List<OpenDrawItem>,
    isLoadingDraws: Boolean,
    isSubmitting: Boolean,
    errorMessage: String?,
    soldTicketResults: List<SellTicketResponse>?,
    currentLanguage: AppLanguage = AppLanguage.CREOLE,
    vendorCode: String = "",
    vendorName: String = "",
    deviceUuid: String = "",
    initialTicketToReplay: VendorTicketItem? = null,
    onResetReplay: () -> Unit = {},
    onBackClick: () -> Unit,
    onSubmitTicket: (selectedDraws: List<OpenDrawItem>, grids: List<BetGrid>) -> Unit,
    onDismissReceipt: () -> Unit,
    onSearchTicketByNumber: ((String, (VendorTicketItem?) -> Unit) -> Unit)? = null
) {
    val context = LocalContext.current
    val scope = rememberCoroutineScope()
    val focusManager = LocalFocusManager.current
    val isCreole = currentLanguage == AppLanguage.CREOLE

    var isPrintingReceipt by remember { mutableStateOf(false) }

    val prefs = remember { PreferencesManager(context) }
    val lotteryName = prefs.getLotteryName()
    val lotterySlogan = prefs.getLotterySlogan()
    val lotteryPhone = prefs.getLotteryPhone()
    val lotteryBankRef = prefs.getLotteryBankRef()
    val lotteryHeaderNote = prefs.getLotteryHeaderNote()
    val lotteryFooterNote = prefs.getLotteryFooterNote()
    val lotteryProvider = prefs.getLotteryProvider()
    val lotteryMariageGratis = prefs.getLotteryMariageGratis()
    val lotteryLogoUrl = prefs.getLotteryLogoUrl()

    // Sélection multi-tirages (1 ou plusieurs tirages en même temps)
    var selectedDrawIds by remember { mutableStateOf<Set<String>>(emptySet()) }
    var showDrawPicker by remember { mutableStateOf(false) }
    var showOptionsMenu by remember { mutableStateOf(false) }
    var showPreValidationPreview by remember { mutableStateOf(false) }
    var showSearchCodeDialog by remember { mutableStateOf(false) }
    var showCombinationDialog by remember { mutableStateOf(false) }
    var searchCodeInput by remember { mutableStateOf("") }
    var isSearchingCode by remember { mutableStateOf(false) }
    var searchCodeError by remember { mutableStateOf<String?>(null) }

    // Initialiser la sélection avec le premier tirage ouvert par défaut
    LaunchedEffect(openDraws) {
        if (selectedDrawIds.isEmpty() && openDraws.isNotEmpty()) {
            selectedDrawIds = setOf(openDraws.first().id)
        }
    }

    // Onglets de jeu : BÒLET, LOTO 3, LOTO 4, LOTO 5, MARYAJ
    val tabs = listOf("BÒLET", "LOTO 3", "LOTO 4", "LOTO 5", "MARYAJ")
    var selectedTabIndex by remember { mutableStateOf(0) }

    // Options par défaut pour Loto 4 et Maryaj
    var defaultLoto4Option by remember { mutableStateOf("TOUT") }
    var defaultMaryajOption by remember { mutableStateOf("TOUT") }

    // Lignes de saisie pour chaque type de jeu (minimum 10)
    val boletLines = remember { mutableStateListOf(*Array(10) { LineItem() }) }
    val loto3Lines = remember { mutableStateListOf(*Array(10) { LineItem() }) }
    val loto4Lines = remember { mutableStateListOf(*Array(10) { LineItem(option = "TOUT") }) }
    val loto5Lines = remember { mutableStateListOf(*Array(10) { LineItem(option = "OP 1") }) }
    val maryajLines = remember { mutableStateListOf(*Array(10) { LineItem(option = "TOUT") }) }

    // Suivi des sources Bòlet pour la combinaison automatique
    var lastBoletSourcesForLoto4 by remember { mutableStateOf<List<String>>(emptyList()) }
    var lastBoletSourcesForMaryaj by remember { mutableStateOf<List<String>>(emptyList()) }

    // Fonctions d'effacement
    fun clearAllLines() {
        boletLines.clear()
        repeat(10) { boletLines.add(LineItem()) }
        loto3Lines.clear()
        repeat(10) { loto3Lines.add(LineItem()) }
        loto4Lines.clear()
        repeat(10) { loto4Lines.add(LineItem(option = "TOUT")) }
        loto5Lines.clear()
        repeat(10) { loto5Lines.add(LineItem(option = "OP 1")) }
        maryajLines.clear()
        repeat(10) { maryajLines.add(LineItem(option = "TOUT")) }
        lastBoletSourcesForLoto4 = emptyList()
        lastBoletSourcesForMaryaj = emptyList()
    }

    // Moteur de combinaison automatique dès le passage sur l'onglet Loto 4 ou Maryaj
    fun autoCombineForTab(tabIndex: Int) {
        val cleanSources = CombinationEngine.extractCleanSources(
            boletLines.map { it.number }
        )
        if (cleanSources.size < 2) return

        // Récupérer le montant par défaut depuis les numéros saisis dans BÒLET
        val defaultAmount = boletLines.firstOrNull { it.number.isNotBlank() && it.amount.isNotBlank() }?.amount ?: ""

        when (tabIndex) {
            2 -> { // Onglet LOTO 4
                val hasExistingNumbers = loto4Lines.any { it.number.isNotBlank() }
                if (cleanSources != lastBoletSourcesForLoto4 || !hasExistingNumbers) {
                    val l4Combos = CombinationEngine.generateLoto4(cleanSources)
                    if (l4Combos.isNotEmpty()) {
                        loto4Lines.clear()
                        l4Combos.forEach { combo ->
                            loto4Lines.add(
                                LineItem(
                                    number = combo.number,
                                    amount = defaultAmount,
                                    option = "TOUT",
                                    sourceNumbers = combo.sourceNumbers,
                                    isAutoGenerated = true
                                )
                            )
                        }
                        while (loto4Lines.size < 10) {
                            loto4Lines.add(LineItem(option = "TOUT"))
                        }
                        lastBoletSourcesForLoto4 = cleanSources
                        Toast.makeText(
                            context,
                            if (isCreole) "${l4Combos.size} Loto 4 konbine otomatikman !" else "${l4Combos.size} Loto 4 combinés automatiquement !",
                            Toast.LENGTH_SHORT
                        ).show()
                    }
                }
            }
            4 -> { // Onglet MARYAJ
                val hasExistingNumbers = maryajLines.any { it.number.isNotBlank() }
                if (cleanSources != lastBoletSourcesForMaryaj || !hasExistingNumbers) {
                    val mCombos = CombinationEngine.generateMariage(cleanSources, separator = "X")
                    if (mCombos.isNotEmpty()) {
                        maryajLines.clear()
                        mCombos.forEach { combo ->
                            maryajLines.add(
                                LineItem(
                                    number = combo.number,
                                    amount = defaultAmount,
                                    option = "TOUT",
                                    isGratis = false,
                                    sourceNumbers = combo.sourceNumbers,
                                    isAutoGenerated = true
                                )
                            )
                        }
                        while (maryajLines.size < 10) {
                            maryajLines.add(LineItem(option = "TOUT"))
                        }
                        lastBoletSourcesForMaryaj = cleanSources
                        Toast.makeText(
                            context,
                            if (isCreole) "${mCombos.size} Maryaj konbine otomatikman !" else "${mCombos.size} Mariages combinés automatiquement !",
                            Toast.LENGTH_SHORT
                        ).show()
                    }
                }
            }
        }
    }

    // Déclenchement automatique dès que l'utilisateur bascule sur Loto 4 ou Maryaj
    LaunchedEffect(selectedTabIndex) {
        if (selectedTabIndex == 2 || selectedTabIndex == 4) {
            autoCombineForTab(selectedTabIndex)
        }
    }

    // Impression automatique dès réception de la confirmation des tickets
    LaunchedEffect(soldTicketResults) {
        val results = soldTicketResults
        if (!results.isNullOrEmpty()) {
            val prefMac = ThermalPrinterService.getPreferredPrinterMac(context)
            if (!prefMac.isNullOrEmpty() || ThermalPrinterService.getPairedPrinters(context).isNotEmpty()) {
                results.forEach { ticket ->
                    ThermalPrinterService.printTicket(context, ticket) { success, msg ->
                        Toast.makeText(context, msg, Toast.LENGTH_SHORT).show()
                    }
                }
            }
        }
    }

    fun loadTicketToEdit(ticket: VendorTicketItem) {
        clearAllLines()
        var bIdx = 0
        var l3Idx = 0
        var l4Idx = 0
        var l5Idx = 0
        var mIdx = 0

        ticket.playedGrids?.forEach { grid ->
            val numStr = grid.numbers.joinToString(if (grid.gameType == "MARIAGE") "x" else "")
            val amtStr = if (grid.isGratis == true) "" else grid.betAmount.toInt().toString()
            val opt = grid.option ?: if (grid.isGratis == true) "GRATIS" else "TOUT"
            val isGratis = grid.isGratis == true
            val item = LineItem(number = numStr, amount = amtStr, option = opt, isGratis = isGratis)

            when (grid.gameType) {
                "BORLETTE", "BOLET" -> {
                    if (bIdx < boletLines.size) boletLines[bIdx] = item else boletLines.add(item)
                    bIdx++
                }
                "LOTO3" -> {
                    if (l3Idx < loto3Lines.size) loto3Lines[l3Idx] = item else loto3Lines.add(item)
                    l3Idx++
                }
                "LOTO4" -> {
                    if (l4Idx < loto4Lines.size) loto4Lines[l4Idx] = item else loto4Lines.add(item)
                    l4Idx++
                }
                "LOTO5" -> {
                    if (l5Idx < loto5Lines.size) loto5Lines[l5Idx] = item else loto5Lines.add(item)
                    l5Idx++
                }
                "MARIAGE", "MARYAJ" -> {
                    if (mIdx < maryajLines.size) maryajLines[mIdx] = item else maryajLines.add(item)
                    mIdx++
                }
                else -> {
                    if (bIdx < boletLines.size) boletLines[bIdx] = item else boletLines.add(item)
                    bIdx++
                }
            }
        }
    }

    // Application des combinaisons générées par le Moteur Intelligent
    fun applyGeneratedCombinations(combos: List<GeneratedCombination>, overwriteDuplicates: Boolean) {
        val l4Combos = combos.filter { it.gameType == EngineGameType.LOTO4 }
        val mCombos = combos.filter { it.gameType == EngineGameType.MARIAGE }
        val l3Combos = combos.filter { it.gameType == EngineGameType.LOTO3 }
        val l5Combos = combos.filter { it.gameType == EngineGameType.LOTO5 }

        fun populate(targetLines: androidx.compose.runtime.snapshots.SnapshotStateList<LineItem>, newCombos: List<GeneratedCombination>) {
            newCombos.forEach { combo ->
                val amtStr = if (combo.betAmount % 1.0 == 0.0) {
                    combo.betAmount.toInt().toString()
                } else {
                    String.format(java.util.Locale.US, "%.2f", combo.betAmount)
                }
                val newItem = LineItem(
                    number = combo.number,
                    amount = amtStr,
                    option = combo.option,
                    isGratis = combo.isGratis,
                    sourceNumbers = combo.sourceNumbers,
                    isAutoGenerated = true,
                    isEdited = combo.isManuallyEdited
                )
                val dupIdx = targetLines.indexOfFirst { it.number.trim() == combo.number.trim() }
                if (dupIdx != -1 && overwriteDuplicates) {
                    targetLines[dupIdx] = newItem
                } else {
                    val emptyIdx = targetLines.indexOfFirst { it.number.isBlank() }
                    if (emptyIdx != -1) {
                        targetLines[emptyIdx] = newItem
                    } else {
                        targetLines.add(newItem)
                    }
                }
            }
        }

        if (l4Combos.isNotEmpty()) {
            populate(loto4Lines, l4Combos)
            lastBoletSourcesForLoto4 = l4Combos.flatMap { it.sourceNumbers }.distinct()
        }
        if (mCombos.isNotEmpty()) {
            populate(maryajLines, mCombos)
            lastBoletSourcesForMaryaj = mCombos.flatMap { it.sourceNumbers }.distinct()
        }
        if (l3Combos.isNotEmpty()) populate(loto3Lines, l3Combos)
        if (l5Combos.isNotEmpty()) populate(loto5Lines, l5Combos)

        // Basculer l'onglet vers le premier jeu enrichi
        if (l4Combos.isNotEmpty()) selectedTabIndex = 2
        else if (mCombos.isNotEmpty()) selectedTabIndex = 4
        else if (l3Combos.isNotEmpty()) selectedTabIndex = 1
        else if (l5Combos.isNotEmpty()) selectedTabIndex = 3

        Toast.makeText(
            context,
            if (isCreole) "${combos.size} konbinezon ajoute ak siksè nan fich la !" else "${combos.size} combinaisons ajoutées au ticket !",
            Toast.LENGTH_SHORT
        ).show()
    }

    // Gestion du Replay / Modification d'une fiche existante
    LaunchedEffect(initialTicketToReplay) {
        initialTicketToReplay?.let { ticket ->
            loadTicketToEdit(ticket)
            Toast.makeText(
                context,
                if (isCreole) "Fich ${ticket.ticketNumber} chaje pou rejoue. Ou ka modifye l !" else "Ticket ${ticket.ticketNumber} chargé pour rejouer.",
                Toast.LENGTH_SHORT
            ).show()
            onResetReplay()
        }
    }

    // Liste active selon l'onglet courant
    val currentLines = when (selectedTabIndex) {
        0 -> boletLines
        1 -> loto3Lines
        2 -> loto4Lines
        3 -> loto5Lines
        else -> maryajLines
    }

    // Longueur max du numéro selon l'onglet
    val maxDigits = when (selectedTabIndex) {
        0 -> 2 // Bòlet (00-99)
        1 -> 3 // Loto 3 (000-999)
        2 -> 4 // Loto 4
        3 -> 5 // Loto 5
        else -> 5 // Maryaj (ex: "12x34" ou "1234")
    }

    val selectedDraws = openDraws.filter { selectedDrawIds.contains(it.id) }
    val lotteryTitle = when {
        selectedDraws.isEmpty() -> if (isCreole) "Chwazi Tiraj" else "Choisir Tirage"
        selectedDraws.size == 1 -> {
            val d = selectedDraws.first()
            val period = d.sessionName ?: TicketReceiptUtil.getDrawPeriod(d.game.name, d.salesClosingAt)
            "${d.game.name} ($period)"
        }
        else -> if (isCreole) "${selectedDraws.size} Tiraj chwazi" else "${selectedDraws.size} Tirages sélectionnés"
    }

    // Calcul du total global sur toutes les grilles saisies
    fun getAllValidGrids(): List<BetGrid> {
        val list = mutableListOf<BetGrid>()

        // 1. BÒLET
        boletLines.forEach { line ->
            val num = line.number.trim()
            val amt = line.amount.toDoubleOrNull() ?: 0.0
            if (num.isNotEmpty() && amt > 0) {
                list.add(BetGrid(numbers = listOf(num), betAmount = amt, multiplier = 1, gameType = "BORLETTE"))
            }
        }

        // 2. LOTO 3
        loto3Lines.forEach { line ->
            val num = line.number.trim()
            val amt = line.amount.toDoubleOrNull() ?: 0.0
            if (num.isNotEmpty() && amt > 0) {
                list.add(BetGrid(numbers = listOf(num), betAmount = amt, multiplier = 1, gameType = "LOTO3"))
            }
        }

        // 3. LOTO 4 (Pas d'options multiples pour Loto 4, standard direct)
        loto4Lines.forEach { line ->
            val num = line.number.trim()
            val amt = line.amount.toDoubleOrNull() ?: 0.0
            if (num.isNotEmpty() && amt > 0) {
                list.add(BetGrid(numbers = listOf(num), betAmount = amt, multiplier = 1, option = "TOUT", gameType = "LOTO4"))
            }
        }

        // 4. LOTO 5 (Options 1, 2, 3 pour Loto 5)
        loto5Lines.forEach { line ->
            val num = line.number.trim()
            val amt = line.amount.toDoubleOrNull() ?: 0.0
            if (num.isNotEmpty() && amt > 0) {
                val optClean = when (line.option.uppercase().replace(" ", "")) {
                    "OP1", "OPTION1", "1" -> "OP1"
                    "OP2", "OPTION2", "2" -> "OP2"
                    "OP3", "OPTION3", "3" -> "OP3"
                    else -> "OP1"
                }
                list.add(BetGrid(numbers = listOf(num), betAmount = amt, multiplier = 1, option = optClean, gameType = "LOTO5"))
            }
        }

        // 5. MARYAJ (TOUT vs GRATIS)
        maryajLines.forEach { line ->
            val raw = line.number.trim()
            val isGratis = line.isGratis || line.option.uppercase().contains("GRATIS")
            val amt = if (isGratis) 0.0 else (line.amount.toDoubleOrNull() ?: 0.0)

            if (raw.isNotEmpty() && (amt > 0 || isGratis)) {
                val parts = if (raw.contains("x") || raw.contains("X") || raw.contains("-") || raw.contains(" ") || raw.contains("*")) {
                    raw.split(Regex("[xX\\-\\s\\*]+")).filter { it.isNotBlank() }
                } else if (raw.length == 4) {
                    listOf(raw.substring(0, 2), raw.substring(2, 4))
                } else {
                    listOf(raw)
                }

                val optClean = if (isGratis) "GRATIS" else "TOUT"
                list.add(BetGrid(numbers = parts, betAmount = amt, multiplier = 1, option = optClean, gameType = "MARIAGE", isGratis = isGratis))
            }
        }

        return list
    }

    val allGrids = getAllValidGrids()
    val unitTotalAmount = allGrids.sumOf { it.betAmount }
    val drawMultiplier = selectedDraws.size.coerceAtLeast(1)
    val grandTotalAmount = unitTotalAmount * drawMultiplier

    Column(
        modifier = Modifier
            .fillMaxSize()
            .background(BodyBg)
    ) {
        // 1. TOP BAR VIOLETTE
        Surface(
            color = TopBarPurple,
            modifier = Modifier.fillMaxWidth()
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 12.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                // Titre de la Loterie sélectionnée (cliquable pour changer de tirage)
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier
                        .clickable { showDrawPicker = true }
                        .padding(vertical = 4.dp)
                ) {
                    Text(
                        text = lotteryTitle,
                        color = Color.White,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Bold
                    )
                    Icon(
                        imageVector = Icons.Default.ArrowDropDown,
                        contentDescription = "Changer tirage",
                        tint = Color.White,
                        modifier = Modifier.size(24.dp)
                    )
                }

                // Actions : ✕ (Fermer) | ✓ (Valider Fiche) | ⋮ (Options)
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    // Bouton ✕ (Annuler / Retour)
                    IconButton(
                        onClick = onBackClick,
                        modifier = Modifier.size(40.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Close,
                            contentDescription = "Fèmen",
                            tint = Color.White,
                            modifier = Modifier.size(24.dp)
                        )
                    }

                    // Bouton ✓ (Aperçu et Validation de la fiche)
                    IconButton(
                        onClick = {
                            val validGrids = getAllValidGrids()
                            if (validGrids.isEmpty()) {
                                Toast.makeText(context, if (isCreole) "Tanpri antre omwen yon nimewo ak montan" else "Entrez au moins un numéro et montant", Toast.LENGTH_SHORT).show()
                            } else if (selectedDraws.isEmpty()) {
                                Toast.makeText(context, if (isCreole) "Chwazi omwen yon tiraj ouvè" else "Choisissez au moins un tirage ouvert", Toast.LENGTH_SHORT).show()
                            } else {
                                showPreValidationPreview = true
                            }
                        },
                        enabled = !isSubmitting,
                        modifier = Modifier.size(40.dp)
                    ) {
                        if (isSubmitting) {
                            CircularProgressIndicator(
                                color = Color.White,
                                strokeWidth = 2.dp,
                                modifier = Modifier.size(20.dp)
                            )
                        } else {
                            Icon(
                                imageVector = Icons.Default.Check,
                                contentDescription = "Valide Fich",
                                tint = Color.White,
                                modifier = Modifier.size(26.dp)
                            )
                        }
                    }

                    // Bouton Recherche Ticket par Code (Modifier / Charger)
                    if (onSearchTicketByNumber != null) {
                        IconButton(
                            onClick = {
                                searchCodeError = null
                                showSearchCodeDialog = true
                            },
                            modifier = Modifier.size(36.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.Search,
                                contentDescription = Strings.t("search_by_code", currentLanguage),
                                tint = Color.White,
                                modifier = Modifier.size(24.dp)
                            )
                        }
                    }

                    // Bouton ⚡ Moteur Konbinezon
                    IconButton(
                        onClick = { showCombinationDialog = true },
                        modifier = Modifier.size(36.dp)
                    ) {
                        Text(
                            text = "⚡",
                            fontSize = 20.sp
                        )
                    }

                    // Bouton ⋮ (Menu Options)
                    Box {
                        IconButton(
                            onClick = { showOptionsMenu = true },
                            modifier = Modifier.size(36.dp)
                        ) {
                            Icon(
                                imageVector = Icons.Default.MoreVert,
                                contentDescription = "Opsyon",
                                tint = Color.White,
                                modifier = Modifier.size(22.dp)
                            )
                        }

                        DropdownMenu(
                            expanded = showOptionsMenu,
                            onDismissRequest = { showOptionsMenu = false }
                        ) {
                            DropdownMenuItem(
                                text = { Text(if (isCreole) "Moteur Konbinezon (Loto 4, Maryaj...)" else "Moteur de Combinaisons") },
                                onClick = {
                                    showOptionsMenu = false
                                    showCombinationDialog = true
                                },
                                leadingIcon = {
                                    Text("⚡", fontSize = 16.sp)
                                }
                            )
                            DropdownMenuItem(
                                text = { Text(if (isCreole) "Efase fich la (Vide)" else "Vider la fiche") },
                                onClick = {
                                    showOptionsMenu = false
                                    clearAllLines()
                                },
                                leadingIcon = {
                                    Icon(Icons.Default.Delete, contentDescription = null, tint = RoeDanger)
                                }
                            )
                            DropdownMenuItem(
                                text = { Text(if (isCreole) "Chwazi Tiraj (Plizyè)" else "Sélectionner Tirages (Multi)") },
                                onClick = {
                                    showOptionsMenu = false
                                    showDrawPicker = true
                                }
                            )
                            if (onSearchTicketByNumber != null) {
                                DropdownMenuItem(
                                    text = { Text(Strings.t("search_by_code", currentLanguage)) },
                                    onClick = {
                                        showOptionsMenu = false
                                        searchCodeError = null
                                        showSearchCodeDialog = true
                                    },
                                    leadingIcon = {
                                        Icon(Icons.Default.Search, contentDescription = null, tint = RoeGold)
                                    }
                                )
                            }
                        }
                    }
                }
            }
        }

        // BARRE RAPIDE DE SÉLECTION MULTI-TIRAGES (CHIPS DÉFILANTS)
        if (openDraws.isNotEmpty()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(Color(0xFF512BD4))
                    .horizontalScroll(rememberScrollState())
                    .padding(horizontal = 10.dp, vertical = 6.dp),
                horizontalArrangement = Arrangement.spacedBy(6.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                openDraws.forEach { draw ->
                    val isSelected = selectedDrawIds.contains(draw.id)
                    Surface(
                        color = if (isSelected) Color.White else Color(0x33FFFFFF),
                        shape = RoundedCornerShape(16.dp),
                        modifier = Modifier.clickable {
                            selectedDrawIds = if (isSelected) {
                                if (selectedDrawIds.size > 1) selectedDrawIds - draw.id else selectedDrawIds
                            } else {
                                selectedDrawIds + draw.id
                            }
                        }
                    ) {
                        Row(
                            modifier = Modifier.padding(horizontal = 10.dp, vertical = 5.dp),
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                        ) {
                            if (isSelected) {
                                Icon(Icons.Default.Check, contentDescription = null, tint = TopBarPurple, modifier = Modifier.size(13.dp))
                            }
                            val drawPeriod = TicketReceiptUtil.getDrawPeriod(draw.game.name, draw.scheduledAt)
                            val cleanGameName = draw.game.name
                                .replace(Regex("(?i)\\s*\\(midi\\s*&\\s*soir\\)"), "")
                                .replace(Regex("(?i)\\s*\\(midi\\)"), "")
                                .replace(Regex("(?i)\\s*\\(soir\\)"), "")
                                .trim()
                            Text(
                                text = "$cleanGameName ($drawPeriod #${draw.drawNumber})",
                                color = if (isSelected) TopBarPurple else Color.White,
                                fontSize = 11.sp,
                                fontWeight = if (isSelected) FontWeight.Black else FontWeight.Medium
                            )
                        }
                    }
                }
            }
        }

        // 2. TABS BAR : BÒLET | LOTO 3 | LOTO 4 | LOTO 5 | MARYAJ
        ScrollableTabRow(
            selectedTabIndex = selectedTabIndex,
            containerColor = TabBarPurple,
            contentColor = Color.White,
            edgePadding = 8.dp,
            indicator = { tabPositions ->
                TabRowDefaults.SecondaryIndicator(
                    Modifier.tabIndicatorOffset(tabPositions[selectedTabIndex]),
                    color = Color.White,
                    height = 3.dp
                )
            }
        ) {
            tabs.forEachIndexed { index, tabName ->
                Tab(
                    selected = selectedTabIndex == index,
                    onClick = {
                        selectedTabIndex = index
                        if (index == 2 || index == 4) {
                            autoCombineForTab(index)
                        }
                    },
                    text = {
                        Text(
                            text = tabName,
                            fontSize = 13.sp,
                            fontWeight = if (selectedTabIndex == index) FontWeight.Black else FontWeight.Bold,
                            color = if (selectedTabIndex == index) Color.White else Color.White.copy(alpha = 0.7f)
                        )
                    }
                )
            }
        }

        // Messages d'erreur éventuels
        errorMessage?.let {
            Surface(
                color = RoeDanger.copy(alpha = 0.15f),
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 6.dp),
                shape = RoundedCornerShape(8.dp)
            ) {
                Text(
                    text = it,
                    color = RoeDanger,
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Bold,
                    modifier = Modifier.padding(8.dp)
                )
            }
        }

        // Bannière d'aide Moteur Intelligent pour BÒLET (si au moins 2 numéros saisis)
        val activeBoletSources = boletLines.map { it.number.trim() }.filter { it.isNotEmpty() }
        if (selectedTabIndex == 0 && activeBoletSources.size >= 2) {
            Surface(
                color = Color(0xFFF3E8FF),
                shape = RoundedCornerShape(8.dp),
                border = BorderStroke(1.dp, Color(0xFFD8B4FE)),
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 12.dp, vertical = 4.dp)
                    .clickable { showCombinationDialog = true }
            ) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 10.dp, vertical = 6.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Text(text = "⚡", fontSize = 16.sp)
                        Column {
                            Text(
                                text = "${activeBoletSources.size} nimewo Bòlet (${activeBoletSources.joinToString(", ")})",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF6B21A8)
                            )
                            Text(
                                text = if (isCreole) "Klike pou jenere Loto 4, Maryaj & kalkile miz" else "Cliquer pour générer Loto 4, Mariage & calcul",
                                fontSize = 10.sp,
                                color = Color(0xFF7E22CE)
                            )
                        }
                    }
                    Surface(
                        color = TopBarPurple,
                        shape = RoundedCornerShape(6.dp),
                        modifier = Modifier.clickable { showCombinationDialog = true }
                    ) {
                        Text(
                            text = if (isCreole) "Jenere" else "Générer",
                            fontSize = 11.sp,
                            fontWeight = FontWeight.Bold,
                            color = Color.White,
                            modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp)
                        )
                    }
                }
            }
        }

        // 3. TABLEAU DES LIGNES DE JEU (Dynamique avec minimum 10)
        LazyColumn(
            modifier = Modifier
                .weight(1f)
                .fillMaxWidth()
                .padding(horizontal = 12.dp, vertical = 4.dp),
            verticalArrangement = Arrangement.spacedBy(2.dp)
        ) {
            items(currentLines.size) { rowIndex ->
                val line = currentLines[rowIndex]
                val isGratisRow = line.isGratis || line.option.uppercase().contains("GRATIS")

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 3.dp),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    // Index (1., 2., 3., ...)
                    Box(
                        modifier = Modifier.width(28.dp),
                        contentAlignment = Alignment.Center
                    ) {
                        Text(
                            text = "${rowIndex + 1}.",
                            color = LineDividerColor,
                            fontSize = 14.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }

                    // Champ 1 : Numéro
                    Box(
                        modifier = Modifier
                            .weight(1.3f)
                            .height(44.dp)
                    ) {
                        Column(
                            modifier = Modifier.fillMaxSize(),
                            verticalArrangement = Arrangement.Center
                        ) {
                            BasicTextField(
                                value = line.number,
                                onValueChange = { newVal ->
                                    val digits = newVal.filter { it.isDigit() || it == 'x' || it == 'X' || it == '-' || it == '*' }
                                    if (digits.length <= maxDigits) {
                                        currentLines[rowIndex] = line.copy(number = digits, isEdited = line.isAutoGenerated)
                                        if (digits.length == maxDigits && rowIndex < currentLines.size - 1) {
                                            focusManager.moveFocus(FocusDirection.Right)
                                        }
                                    }
                                },
                                textStyle = TextStyle(
                                    color = TextDarkColor,
                                    fontSize = 18.sp,
                                    fontWeight = FontWeight.Black,
                                    fontFamily = FontFamily.Monospace
                                ),
                                singleLine = true,
                                keyboardOptions = KeyboardOptions(
                                    keyboardType = if (selectedTabIndex == 4) KeyboardType.Text else KeyboardType.Number,
                                    imeAction = ImeAction.Next
                                ),
                                keyboardActions = KeyboardActions(
                                    onNext = { focusManager.moveFocus(FocusDirection.Right) }
                                ),
                                cursorBrush = SolidColor(TopBarPurple),
                                decorationBox = { innerTextField ->
                                    Box(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 4.dp),
                                        contentAlignment = Alignment.CenterStart
                                    ) {
                                        if (line.number.isEmpty()) {
                                            Text(
                                                text = when (selectedTabIndex) {
                                                    0 -> "00"
                                                    1 -> "000"
                                                    2 -> "0000"
                                                    3 -> "00000"
                                                    else -> "12x34"
                                                },
                                                color = PlaceholderColor,
                                                fontSize = 16.sp,
                                                fontWeight = FontWeight.Medium
                                            )
                                        }
                                        innerTextField()
                                    }
                                }
                            )
                            HorizontalDivider(
                                color = if (line.number.isNotEmpty()) TopBarPurple else LineDividerColor,
                                thickness = 1.dp
                            )
                        }
                    }

                    // Sélecteur d'Options :
                    // Note : LOTO 4 (index 2) n'a pas plusieurs options (standard direct).
                    // Les options multiples sont pour LOTO 5 (index 3 : OP 1, OP 2, OP 3) et MARYAJ (index 4 : TOUT vs GRATIS).
                    if (selectedTabIndex == 3) {
                        // LOTO 5 : Options 1, 2, 3
                        Box(
                            modifier = Modifier
                                .width(68.dp)
                                .height(38.dp)
                                .clickable {
                                    val nextOpt = when (line.option.uppercase().replace(" ", "")) {
                                        "OP1", "1" -> "OP 2"
                                        "OP2", "2" -> "OP 3"
                                        "OP3", "3" -> "OP 1"
                                        else -> "OP 1"
                                    }
                                    currentLines[rowIndex] = line.copy(option = nextOpt, isEdited = line.isAutoGenerated)
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Surface(
                                color = TopBarPurple.copy(alpha = 0.12f),
                                shape = RoundedCornerShape(6.dp),
                                border = androidx.compose.foundation.BorderStroke(1.dp, TopBarPurple)
                            ) {
                                Text(
                                    text = if (line.option.isNotBlank()) line.option else "OP 1",
                                    color = TopBarPurple,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Black,
                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 4.dp)
                                )
                            }
                        }
                    } else if (selectedTabIndex == 4) {
                        // MARYAJ : TOUT vs GRATIS
                        Box(
                            modifier = Modifier
                                .width(68.dp)
                                .height(38.dp)
                                .clickable {
                                    val nextOpt = if (line.option.uppercase() == "GRATIS" || line.isGratis) "TOUT" else "GRATIS"
                                    val gratisFlag = nextOpt == "GRATIS"
                                    val newAmount = if (gratisFlag) "" else line.amount
                                    currentLines[rowIndex] = line.copy(option = nextOpt, isGratis = gratisFlag, amount = newAmount, isEdited = line.isAutoGenerated)
                                },
                            contentAlignment = Alignment.Center
                        ) {
                            Surface(
                                color = if (isGratisRow) Color(0xFF2E7D32).copy(alpha = 0.15f) else TopBarPurple.copy(alpha = 0.12f),
                                shape = RoundedCornerShape(6.dp),
                                border = androidx.compose.foundation.BorderStroke(
                                    1.dp,
                                    if (isGratisRow) Color(0xFF2E7D32) else TopBarPurple
                                )
                            ) {
                                Text(
                                    text = if (isGratisRow) "GRATIS" else "TOUT",
                                    color = if (isGratisRow) Color(0xFF2E7D32) else TopBarPurple,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Black,
                                    modifier = Modifier.padding(horizontal = 6.dp, vertical = 4.dp)
                                )
                            }
                        }
                    }

                    // Champ 2 : Montant
                    Box(
                        modifier = Modifier
                            .weight(1.3f)
                            .height(44.dp)
                    ) {
                        Column {
                            Box(
                                modifier = Modifier
                                    .weight(1f)
                                    .fillMaxWidth(),
                                contentAlignment = Alignment.CenterStart
                            ) {
                                BasicTextField(
                                    value = if (isGratisRow) "GRATIS" else line.amount,
                                    onValueChange = { newVal ->
                                        if (!isGratisRow) {
                                            val digits = newVal.filter { it.isDigit() }
                                            if (digits.length <= 6) {
                                                currentLines[rowIndex] = line.copy(amount = digits, isEdited = line.isAutoGenerated)
                                            }
                                        }
                                    },
                                    readOnly = isGratisRow,
                                    textStyle = TextStyle(
                                        color = if (isGratisRow) Color(0xFF2E7D32) else TextDarkColor,
                                        fontSize = 16.sp,
                                        fontWeight = FontWeight.Black,
                                        fontFamily = FontFamily.Monospace
                                    ),
                                    singleLine = true,
                                    keyboardOptions = KeyboardOptions(
                                        keyboardType = KeyboardType.Number,
                                        imeAction = if (rowIndex < currentLines.size - 1) ImeAction.Next else ImeAction.Done
                                    ),
                                    keyboardActions = KeyboardActions(
                                        onNext = { focusManager.moveFocus(FocusDirection.Down) },
                                        onDone = { focusManager.clearFocus() }
                                    ),
                                    cursorBrush = SolidColor(TopBarPurple),
                                    decorationBox = { innerTextField ->
                                        Box(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(vertical = 4.dp)
                                        ) {
                                            if (line.amount.isEmpty() && !isGratisRow) {
                                                Text(
                                                    text = "Montan",
                                                    color = PlaceholderColor,
                                                    fontSize = 15.sp,
                                                    fontWeight = FontWeight.Medium
                                                )
                                            }
                                            innerTextField()
                                        }
                                    }
                                )
                            }
                            HorizontalDivider(
                                color = if (isGratisRow) Color(0xFF2E7D32) else if (line.amount.isNotEmpty()) TopBarPurple else LineDividerColor,
                                thickness = 1.dp
                            )
                        }
                    }
                }
            }
        }

        // 4. BARRE DE TOTAL EN BAS DE LA FICHE
        Surface(
            color = Color.White,
            shadowElevation = 8.dp,
            modifier = Modifier.fillMaxWidth()
        ) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(horizontal = 16.dp, vertical = 10.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceBetween
            ) {
                Column {
                    Text(
                        text = "TOTAL FICH",
                        color = PlaceholderColor,
                        fontSize = 10.sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 1.sp
                    )
                    Text(
                        text = "${String.format("%.2f", grandTotalAmount)} HTG",
                        color = TopBarPurple,
                        fontSize = 18.sp,
                        fontWeight = FontWeight.Black,
                        fontFamily = FontFamily.Monospace
                    )
                    if (selectedDraws.size > 1) {
                        Text(
                            text = "${String.format("%.2f", unitTotalAmount)} G x ${selectedDraws.size} tiraj",
                            color = Color(0xFF616161),
                            fontSize = 10.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }

                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = "${allGrids.size} jwèt",
                        color = TextDarkColor,
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold
                    )

                    Button(
                        onClick = {
                            val validGrids = getAllValidGrids()
                            if (validGrids.isEmpty()) {
                                Toast.makeText(context, if (isCreole) "Tanpri antre omwen yon nimewo ak montan" else "Entrez au moins un numéro et montant", Toast.LENGTH_SHORT).show()
                            } else if (selectedDraws.isEmpty()) {
                                Toast.makeText(context, if (isCreole) "Chwazi omwen yon tiraj ouvè" else "Choisissez au moins un tirage ouvert", Toast.LENGTH_SHORT).show()
                            } else {
                                showPreValidationPreview = true
                            }
                        },
                        enabled = allGrids.isNotEmpty() && !isSubmitting,
                        colors = ButtonDefaults.buttonColors(containerColor = TopBarPurple),
                        shape = RoundedCornerShape(10.dp),
                        contentPadding = PaddingValues(horizontal = 16.dp, vertical = 8.dp)
                    ) {
                        Text(
                            text = if (isSubmitting) "Vant..." else "FÈ FICH LA",
                            color = Color.White,
                            fontSize = 13.sp,
                            fontWeight = FontWeight.Black
                        )
                    }
                }
            }
        }
    }

    // Modal de sélection Multi-Tirages (Georgia, New York, Florida) - Tendance Bleu & Blanc
    if (showDrawPicker) {
        AlertDialog(
            onDismissRequest = { showDrawPicker = false },
            containerColor = Color.White,
            shape = RoundedCornerShape(16.dp),
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Text(
                        text = Strings.t("multi_draws_select", currentLanguage),
                        fontWeight = FontWeight.Black,
                        fontSize = 17.sp,
                        color = Color(0xFF1E3A8A) // Bleu Royal Profond
                    )
                }
            },
            text = {
                if (openDraws.isEmpty()) {
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 12.dp),
                        horizontalAlignment = Alignment.CenterHorizontally
                    ) {
                        Text(
                            text = if (isCreole) "Pa gen okenn tiraj ki ouvè pou kounye a." else "Aucun tirage ouvert actuellement.",
                            color = Color(0xFF475569),
                            fontSize = 13.sp,
                            textAlign = TextAlign.Center
                        )
                        Spacer(modifier = Modifier.height(6.dp))
                        Text(
                            text = if (isCreole) "Tiraj yo ouvè chak jou apati 07:00 AM (Lè Ayiti)." else "Les ventes ouvrent chaque jour dès 07:00 AM (Heure d'Haïti).",
                            color = Color(0xFF64748B),
                            fontSize = 11.sp,
                            textAlign = TextAlign.Center
                        )
                    }
                } else {
                    Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            TextButton(
                                onClick = {
                                    selectedDrawIds = openDraws.map { it.id }.toSet()
                                }
                            ) {
                                Text(
                                    text = if (isCreole) "Tout chwazi" else "Tout sélectionner",
                                    color = Color(0xFF2563EB),
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 13.sp
                                )
                            }

                            Text(
                                text = "${selectedDrawIds.size} / ${openDraws.size}",
                                color = Color(0xFF64748B),
                                fontSize = 13.sp,
                                fontWeight = FontWeight.Bold
                            )
                        }

                        openDraws.forEach { draw ->
                            val isChecked = selectedDrawIds.contains(draw.id)
                            Surface(
                                color = if (isChecked) Color(0xFFEFF6FF) else Color(0xFFF8FAFC),
                                shape = RoundedCornerShape(10.dp),
                                border = androidx.compose.foundation.BorderStroke(
                                    width = if (isChecked) 2.dp else 1.dp,
                                    color = if (isChecked) Color(0xFF2563EB) else Color(0xFFCBD5E1)
                                ),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable {
                                        selectedDrawIds = if (isChecked) {
                                            if (selectedDrawIds.size > 1) selectedDrawIds - draw.id else selectedDrawIds
                                        } else {
                                            selectedDrawIds + draw.id
                                        }
                                    }
                            ) {
                                Row(
                                    modifier = Modifier
                                        .fillMaxWidth()
                                        .padding(12.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Column(modifier = Modifier.weight(1f)) {
                                        Row(
                                            verticalAlignment = Alignment.CenterVertically,
                                            horizontalArrangement = Arrangement.spacedBy(6.dp)
                                        ) {
                                            Text(
                                                text = draw.game.name,
                                                fontWeight = FontWeight.Black,
                                                fontSize = 15.sp,
                                                color = if (isChecked) Color(0xFF1E3A8A) else Color(0xFF0F172A)
                                            )
                                            val period = draw.sessionName ?: TicketReceiptUtil.getDrawPeriod(draw.game.name, draw.salesClosingAt)
                                            DrawPeriodBadge(period = period)
                                        }
                                        Spacer(modifier = Modifier.height(3.dp))
                                        val closingHaiti = TicketReceiptUtil.formatHaitiTimeOnly(draw.salesClosingAt)
                                        Text(
                                            text = "Tiraj N° ${draw.drawNumber} • Fèmen a : $closingHaiti",
                                            fontSize = 12.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = if (isChecked) Color(0xFF2563EB) else Color(0xFF475569)
                                        )
                                    }

                                    Checkbox(
                                        checked = isChecked,
                                        onCheckedChange = { checked ->
                                            selectedDrawIds = if (checked) {
                                                selectedDrawIds + draw.id
                                            } else {
                                                if (selectedDrawIds.size > 1) selectedDrawIds - draw.id else selectedDrawIds
                                            }
                                        },
                                        colors = CheckboxDefaults.colors(
                                            checkedColor = Color(0xFF2563EB),
                                            uncheckedColor = Color(0xFF94A3B8),
                                            checkmarkColor = Color.White
                                        )
                                    )
                                }
                            }
                        }
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = { showDrawPicker = false },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2563EB)),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = if (isCreole) "Valide & Fèmen" else "Confirmer & Fermer",
                        color = Color.White,
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        )
    }

    // Modal Reçu Ticket Vendu Multi-Tirages ("Fich yo reyisi")
    if (!soldTicketResults.isNullOrEmpty()) {
        val totalSoldAmount = soldTicketResults.sumOf { it.totalAmount }
        AlertDialog(
            onDismissRequest = {
                clearAllLines()
                onDismissReceipt()
            },
            containerColor = Color.White,
            shape = RoundedCornerShape(16.dp),
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text(
                            text = if (soldTicketResults.size == 1) "FICH LA ENPRIME AK SIKSE !" else "${soldTicketResults.size} FICH ENPRIME AK SIKSE !",
                            color = Color(0xFF2E7D32),
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = if (isCreole) "Tikè ofisyèl ki anrejistre sou sèvè a" else "Tickets officiels enregistrés sur le serveur",
                            color = Color.Gray,
                            fontSize = 11.sp
                        )
                    }
                    IconButton(
                        onClick = {
                            clearAllLines()
                            onDismissReceipt()
                        },
                        modifier = Modifier.size(28.dp)
                    ) {
                        Icon(Icons.Default.Close, contentDescription = "Fèmen", tint = Color.Gray)
                    }
                }
            },
            text = {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 480.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    items(soldTicketResults) { ticket ->
                        Surface(
                            color = Color.White,
                            shape = RoundedCornerShape(8.dp),
                            border = BorderStroke(1.dp, Color(0xFFE0E0E0)),
                            shadowElevation = 2.dp,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Column(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(12.dp),
                                horizontalAlignment = Alignment.CenterHorizontally
                            ) {
                                // 1. Logo & En-tête Loterie
                                LotteryLogoView(logoUrl = lotteryLogoUrl)
                                Text(
                                    text = lotteryHeaderNote,
                                    color = Color(0xFF616161),
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold,
                                    letterSpacing = 1.sp
                                )
                                Text(
                                    text = lotteryName.uppercase(),
                                    color = Color.Black,
                                    fontWeight = FontWeight.Black,
                                    fontSize = 15.sp,
                                    textAlign = TextAlign.Center
                                )
                                if (lotterySlogan.isNotEmpty()) {
                                    Text(
                                        text = lotterySlogan,
                                        color = Color(0xFF424242),
                                        fontWeight = FontWeight.Medium,
                                        fontSize = 11.sp
                                    )
                                }
                                Text(
                                    text = if (lotteryBankRef.isNotEmpty()) "$lotteryBankRef • Tel: $lotteryPhone" else "Tel: $lotteryPhone",
                                    color = Color(0xFF616161),
                                    fontSize = 10.sp
                                )
                                Text(
                                    text = "POS: ${ticket.vendorCode ?: deviceUuid.take(16)}",
                                    color = Color(0xFF757575),
                                    fontSize = 10.sp,
                                    fontFamily = FontFamily.Monospace
                                )
                                val ticketDate = ticket.createdAt?.take(19)?.replace("T", " ")
                                    ?: java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US).format(java.util.Date())
                                Text(
                                    text = "Dat & Lè: $ticketDate",
                                    color = Color(0xFF212121),
                                    fontWeight = FontWeight.Bold,
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace
                                )

                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "********************************",
                                    color = Color(0xFFBDBDBD),
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace,
                                    fontWeight = FontWeight.Bold
                                )

                                // 2. Nom du Tirage & Identification MIDI / SOIR
                                val schedOrCreated = ticket.scheduledAt ?: ticket.createdAt
                                val drawDisplayName = TicketReceiptUtil.formatDrawDisplayName(
                                    ticket.gameName,
                                    ticket.drawNumber,
                                    schedOrCreated
                                )
                                val drawPeriod = TicketReceiptUtil.getDrawPeriod(ticket.gameName, schedOrCreated)

                                Text(
                                    text = drawDisplayName,
                                    color = Color.Black,
                                    fontWeight = FontWeight.Black,
                                    fontSize = 13.sp,
                                    textAlign = TextAlign.Center
                                )
                                DrawPeriodBadge(period = drawPeriod)
                                Text(
                                    text = "#Ticket: ${ticket.ticketNumber}",
                                    color = Color.Black,
                                    fontSize = 12.sp,
                                    fontFamily = FontFamily.Monospace,
                                    fontWeight = FontWeight.Black
                                )

                                Text(
                                    text = "********************************",
                                    color = Color(0xFFBDBDBD),
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.height(3.dp))

                                // 3. Grilles jouées
                                val gridsToDisplay = ticket.playedGrids ?: getAllValidGrids()
                                val regularGrids = gridsToDisplay.filter { it.isGratis != true }
                                val gratisGrids = gridsToDisplay.filter { it.isGratis == true }

                                regularGrids.forEach { g ->
                                    val gameLabel = TicketReceiptUtil.formatGameLabel(g.gameType, g.numbers)
                                    val formattedNumbers = TicketReceiptUtil.formatGridNumbers(g.gameType, g.numbers)
                                    Row(
                                        modifier = Modifier
                                            .fillMaxWidth()
                                            .padding(vertical = 1.5.dp),
                                        horizontalArrangement = Arrangement.SpaceBetween,
                                        verticalAlignment = Alignment.CenterVertically
                                    ) {
                                        Text(
                                            text = "$gameLabel  $formattedNumbers",
                                            color = Color.Black,
                                            fontSize = 12.sp,
                                            fontFamily = FontFamily.Monospace,
                                            fontWeight = FontWeight.Bold
                                        )
                                        Text(
                                            text = "${String.format("%.0f", g.betAmount)} HTG",
                                            color = Color.Black,
                                            fontSize = 12.sp,
                                            fontFamily = FontFamily.Monospace,
                                            fontWeight = FontWeight.Black
                                        )
                                    }
                                }

                                if (gratisGrids.isNotEmpty()) {
                                    Spacer(modifier = Modifier.height(4.dp))
                                    Text(
                                        text = "Mariage Gratuit",
                                        color = Color(0xFF424242),
                                        fontWeight = FontWeight.Bold,
                                        fontSize = 11.sp
                                    )
                                    gratisGrids.forEach { g ->
                                        val formattedGratis = TicketReceiptUtil.formatGridNumbers("MARIAGE", g.numbers)
                                        Row(
                                            modifier = Modifier
                                                .fillMaxWidth()
                                                .padding(vertical = 1.dp),
                                            horizontalArrangement = Arrangement.SpaceBetween,
                                            verticalAlignment = Alignment.CenterVertically
                                        ) {
                                            Text(
                                                text = "Mariage  $formattedGratis",
                                                color = Color(0xFF616161),
                                                fontSize = 11.sp,
                                                fontFamily = FontFamily.Monospace
                                            )
                                            Text(
                                                text = "xxxx HTG",
                                                color = Color(0xFF757575),
                                                fontSize = 11.sp,
                                                fontFamily = FontFamily.Monospace
                                            )
                                        }
                                    }
                                }

                                Spacer(modifier = Modifier.height(4.dp))
                                Text(
                                    text = "********************************",
                                    color = Color(0xFFBDBDBD),
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace,
                                    fontWeight = FontWeight.Bold
                                )

                                // 4. Total
                                Row(
                                    modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp),
                                    horizontalArrangement = Arrangement.SpaceBetween,
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(text = "TOTAL", color = Color.Black, fontWeight = FontWeight.Black, fontSize = 13.sp)
                                    Text(
                                        text = "${String.format("%.0f", ticket.totalAmount)} HTG",
                                        color = Color.Black,
                                        fontWeight = FontWeight.Black,
                                        fontSize = 15.sp,
                                        fontFamily = FontFamily.Monospace
                                    )
                                }

                                Text(
                                    text = "********************************",
                                    color = Color(0xFFBDBDBD),
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace,
                                    fontWeight = FontWeight.Bold
                                )
                                Spacer(modifier = Modifier.height(6.dp))

                                // 5. Code-barres scannable officiel Code 128
                                Barcode128View(
                                    code = ticket.ticketNumber,
                                    height = 42.dp,
                                    showCodeText = true
                                )
                                Text(
                                    text = "Siyati : ${(ticket.secureChecksum).take(22)}...",
                                    color = Color.Gray,
                                    fontSize = 9.sp,
                                    fontFamily = FontFamily.Monospace
                                )
                                Spacer(modifier = Modifier.height(4.dp))

                                // 6. Mentions légales & Footer
                                Text(
                                    text = lotteryFooterNote,
                                    color = Color(0xFF424242),
                                    fontSize = 9.sp,
                                    textAlign = TextAlign.Center,
                                    lineHeight = 12.sp,
                                    fontWeight = FontWeight.Medium
                                )
                                if (lotteryMariageGratis.isNotEmpty()) {
                                    Text(
                                        text = lotteryMariageGratis,
                                        color = Color(0xFF2E7D32),
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center
                                    )
                                }
                                Text(
                                    text = lotteryProvider,
                                    color = Color(0xFF757575),
                                    fontSize = 8.sp,
                                    fontWeight = FontWeight.Bold,
                                    textAlign = TextAlign.Center
                                )
                            }
                        }
                    }
                }
            },
            dismissButton = {
                OutlinedButton(
                    onClick = {
                        if (isPrintingReceipt) return@OutlinedButton
                        isPrintingReceipt = true
                        scope.launch {
                            soldTicketResults.forEach { ticket ->
                                ThermalPrinterService.printTicket(context, ticket) { success, msg ->
                                    Toast.makeText(context, msg, Toast.LENGTH_SHORT).show()
                                }
                            }
                            isPrintingReceipt = false
                        }
                    },
                    shape = RoundedCornerShape(8.dp),
                    colors = ButtonDefaults.outlinedButtonColors(contentColor = Color(0xFF1E293B)),
                    border = BorderStroke(1.dp, Color(0xFFCBD5E1))
                ) {
                    if (isPrintingReceipt) {
                        CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = TopBarPurple)
                        Spacer(modifier = Modifier.width(4.dp))
                    } else {
                        Icon(Icons.Default.Print, contentDescription = null, modifier = Modifier.size(16.dp), tint = TopBarPurple)
                        Spacer(modifier = Modifier.width(4.dp))
                    }
                    Text(
                        text = if (isCreole) "ENPRIME" else "IMPRIMER",
                        fontWeight = FontWeight.Bold,
                        fontSize = 12.sp
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        clearAllLines()
                        onDismissReceipt()
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = TopBarPurple),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Icon(Icons.Default.Add, contentDescription = null, tint = Color.White)
                    Spacer(modifier = Modifier.width(6.dp))
                    Text(
                        if (isCreole) "FÈ YON LÒT FICH" else "FAIRE UN AUTRE TICKET",
                        color = Color.White,
                        fontWeight = FontWeight.Black
                    )
                }
            }
        )
    }

    // MODAL APERÇU AVANT VALIDATION & IMPRESSION (Pre-validation Preview)
    if (showPreValidationPreview) {
        val validGrids = getAllValidGrids()
        AlertDialog(
            onDismissRequest = { showPreValidationPreview = false },
            containerColor = Color.White,
            shape = RoundedCornerShape(16.dp),
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text(
                            text = Strings.t("pre_validation_preview", currentLanguage),
                            color = TopBarPurple,
                            fontSize = 15.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = Strings.t("verify_numbers_amounts", currentLanguage),
                            color = Color.Gray,
                            fontSize = 11.sp
                        )
                    }
                    IconButton(onClick = { showPreValidationPreview = false }, modifier = Modifier.size(28.dp)) {
                        Icon(Icons.Default.Close, contentDescription = "Fermer", tint = Color.Gray)
                    }
                }
            },
            text = {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 2.dp),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    // Logo & En-tête Loterie (Identique à la fiche Borlette réelle)
                    LotteryLogoView(logoUrl = lotteryLogoUrl)
                    Text(
                        text = lotteryHeaderNote,
                        color = Color(0xFF616161),
                        fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        letterSpacing = 1.sp
                    )
                    Text(
                        text = lotteryName.uppercase(),
                        color = Color.Black,
                        fontWeight = FontWeight.Black,
                        fontSize = 16.sp,
                        textAlign = TextAlign.Center
                    )
                    if (lotterySlogan.isNotEmpty()) {
                        Text(
                            text = lotterySlogan,
                            color = Color(0xFF424242),
                            fontWeight = FontWeight.Medium,
                            fontSize = 12.sp
                        )
                    }
                    Text(
                        text = if (lotteryBankRef.isNotEmpty()) "$lotteryBankRef • Tel: $lotteryPhone" else "Tel: $lotteryPhone",
                        color = Color(0xFF616161),
                        fontSize = 11.sp
                    )
                    if (deviceUuid.isNotEmpty()) {
                        Text(
                            text = "POS: ${deviceUuid.take(16)}",
                            color = Color(0xFF757575),
                            fontSize = 10.sp,
                            fontFamily = FontFamily.Monospace
                        )
                    }
                    val nowFormatted = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale.US).format(java.util.Date())
                    Text(
                        text = "Dat & Lè: $nowFormatted",
                        color = Color(0xFF212121),
                        fontWeight = FontWeight.Bold,
                        fontSize = 11.sp,
                        fontFamily = FontFamily.Monospace
                    )

                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "********************************",
                        color = Color(0xFFBDBDBD),
                        fontSize = 11.sp,
                        fontFamily = FontFamily.Monospace,
                        fontWeight = FontWeight.Bold
                    )

                    // Nom du ou des Tirages avec Identification MIDI / SOIR
                    selectedDraws.forEach { d ->
                        val drawDisplayName = TicketReceiptUtil.formatDrawDisplayName(
                            d.game.name,
                            d.drawNumber,
                            d.scheduledAt
                        )
                        val drawPeriod = TicketReceiptUtil.getDrawPeriod(d.game.name, d.scheduledAt)
                        Text(
                            text = drawDisplayName,
                            color = Color.Black,
                            fontWeight = FontWeight.Bold,
                            fontSize = 13.sp,
                            textAlign = TextAlign.Center
                        )
                        DrawPeriodBadge(period = drawPeriod)
                    }

                    Text(
                        text = "********************************",
                        color = Color(0xFFBDBDBD),
                        fontSize = 11.sp,
                        fontFamily = FontFamily.Monospace,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.height(3.dp))

                    // Grilles régulières
                    val regularGrids = validGrids.filter { it.isGratis != true }
                    val gratisGrids = validGrids.filter { it.isGratis == true }

                    regularGrids.forEach { g ->
                        val gameLabel = TicketReceiptUtil.formatGameLabel(g.gameType, g.numbers)
                        val formattedNumbers = TicketReceiptUtil.formatGridNumbers(g.gameType, g.numbers)
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 1.5.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = "$gameLabel  $formattedNumbers",
                                color = Color.Black,
                                fontSize = 12.sp,
                                fontFamily = FontFamily.Monospace,
                                fontWeight = FontWeight.Bold
                            )
                            Text(
                                text = "${String.format("%.0f", g.betAmount)} HTG",
                                color = Color.Black,
                                fontSize = 12.sp,
                                fontFamily = FontFamily.Monospace,
                                fontWeight = FontWeight.Black
                            )
                        }
                    }

                    // Grilles gratuites (Mariage Gratuit)
                    if (gratisGrids.isNotEmpty()) {
                        Spacer(modifier = Modifier.height(4.dp))
                        Text(
                            text = "Mariage Gratuit",
                            color = Color(0xFF424242),
                            fontWeight = FontWeight.Bold,
                            fontSize = 11.sp
                        )
                        gratisGrids.forEach { g ->
                            val formattedGratis = TicketReceiptUtil.formatGridNumbers("MARIAGE", g.numbers)
                            Row(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 1.dp),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = "Mariage  $formattedGratis",
                                    color = Color(0xFF616161),
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace
                                )
                                Text(
                                    text = "xxxx HTG",
                                    color = Color(0xFF757575),
                                    fontSize = 11.sp,
                                    fontFamily = FontFamily.Monospace
                                )
                            }
                        }
                    }

                    Spacer(modifier = Modifier.height(4.dp))
                    Text(
                        text = "********************************",
                        color = Color(0xFFBDBDBD),
                        fontSize = 11.sp,
                        fontFamily = FontFamily.Monospace,
                        fontWeight = FontWeight.Bold
                    )

                    // Total
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp),
                        horizontalArrangement = Arrangement.SpaceBetween,
                        verticalAlignment = Alignment.CenterVertically
                    ) {
                        Text(text = "TOTAL", color = Color.Black, fontWeight = FontWeight.Black, fontSize = 13.sp)
                        Column(horizontalAlignment = Alignment.End) {
                            Text(
                                text = "${String.format("%.0f", grandTotalAmount)} HTG",
                                color = Color.Black,
                                fontWeight = FontWeight.Black,
                                fontSize = 15.sp,
                                fontFamily = FontFamily.Monospace
                            )
                            if (selectedDraws.size > 1) {
                                Text(
                                    text = "${String.format("%.0f", unitTotalAmount)} G x ${selectedDraws.size} tiraj",
                                    color = Color.Gray,
                                    fontSize = 10.sp,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }

                    Text(
                        text = "********************************",
                        color = Color(0xFFBDBDBD),
                        fontSize = 11.sp,
                        fontFamily = FontFamily.Monospace,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(modifier = Modifier.height(4.dp))

                    // Code-barres scannable officiel Code 128 (Aperçu)
                    Barcode128View(
                        code = "ROE-${java.text.SimpleDateFormat("yyyyMMdd", java.util.Locale.US).format(java.util.Date())}-PREVIEW",
                        height = 42.dp,
                        showCodeText = true
                    )
                    Text(
                        text = if (isCreole) "Apèsi kòd-bar avan enpresyon" else "Aperçu code-barres avant impression",
                        color = Color.Gray,
                        fontSize = 9.sp,
                        fontFamily = FontFamily.Monospace
                    )
                    Spacer(modifier = Modifier.height(4.dp))

                    // Mentions légales & Footer
                    Text(
                        text = lotteryFooterNote,
                        color = Color(0xFF424242),
                        fontSize = 9.sp,
                        textAlign = TextAlign.Center,
                        lineHeight = 12.sp,
                        fontWeight = FontWeight.Medium
                    )
                    if (lotteryMariageGratis.isNotEmpty()) {
                        Text(
                            text = lotteryMariageGratis,
                            color = Color(0xFF2E7D32),
                            fontSize = 9.sp,
                            fontWeight = FontWeight.Bold,
                            textAlign = TextAlign.Center
                        )
                    }
                    Text(
                        text = lotteryProvider,
                        color = Color(0xFF757575),
                        fontSize = 8.sp,
                        fontWeight = FontWeight.Bold,
                        textAlign = TextAlign.Center
                    )
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        showPreValidationPreview = false
                        onSubmitTicket(selectedDraws, validGrids)
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2E7D32)),
                    shape = RoundedCornerShape(8.dp),
                    contentPadding = PaddingValues(horizontal = 14.dp, vertical = 8.dp)
                ) {
                    Icon(Icons.Default.Check, contentDescription = null, modifier = Modifier.size(16.dp))
                    Spacer(modifier = Modifier.width(4.dp))
                    Text(
                        text = Strings.t("confirm_and_print", currentLanguage),
                        color = Color.White,
                        fontWeight = FontWeight.Black,
                        fontSize = 12.sp
                    )
                }
            },
            dismissButton = {
                OutlinedButton(
                    onClick = { showPreValidationPreview = false },
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = Strings.t("modify_ticket", currentLanguage),
                        color = Color(0xFF616161),
                        fontWeight = FontWeight.Bold,
                        fontSize = 12.sp
                    )
                }
            }
        )
    }

    // MODAL DE RECHERCHE DE TICKET PAR CODE (POUR MODIFIER OU RÉIMPRIMER)
    if (showSearchCodeDialog && onSearchTicketByNumber != null) {
        AlertDialog(
            onDismissRequest = { if (!isSearchingCode) showSearchCodeDialog = false },
            containerColor = Color.White,
            shape = RoundedCornerShape(16.dp),
            title = {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text(
                            text = Strings.t("search_ticket_code_title", currentLanguage),
                            color = TopBarPurple,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Black
                        )
                        Text(
                            text = Strings.t("search_ticket_code_sub", currentLanguage),
                            color = Color.Gray,
                            fontSize = 11.sp
                        )
                    }
                    IconButton(onClick = { showSearchCodeDialog = false }, modifier = Modifier.size(28.dp)) {
                        Icon(Icons.Default.Close, contentDescription = "Fermer", tint = Color.Gray)
                    }
                }
            },
            text = {
                Column(modifier = Modifier.fillMaxWidth()) {
                    OutlinedTextField(
                        value = searchCodeInput,
                        onValueChange = {
                            searchCodeInput = it.uppercase()
                            searchCodeError = null
                        },
                        placeholder = { Text(Strings.t("ticket_code_placeholder", currentLanguage), fontSize = 12.sp) },
                        singleLine = true,
                        leadingIcon = {
                            Icon(Icons.Default.QrCodeScanner, contentDescription = null, tint = TopBarPurple)
                        },
                        trailingIcon = {
                            if (searchCodeInput.isNotEmpty()) {
                                IconButton(onClick = { searchCodeInput = "" }) {
                                    Icon(Icons.Default.Close, contentDescription = "Effacer", tint = Color.Gray)
                                }
                            }
                        },
                        colors = OutlinedTextFieldDefaults.colors(
                            focusedTextColor = Color.Black,
                            unfocusedTextColor = Color.Black,
                            focusedBorderColor = TopBarPurple,
                            unfocusedBorderColor = Color(0xFFBDBDBD)
                        ),
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(10.dp)
                    )

                    if (searchCodeError != null) {
                        Spacer(modifier = Modifier.height(8.dp))
                        Text(
                            text = searchCodeError ?: "",
                            color = Color(0xFFD32F2F),
                            fontSize = 12.sp,
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        val code = searchCodeInput.trim()
                        if (code.isNotEmpty()) {
                            isSearchingCode = true
                            searchCodeError = null
                            onSearchTicketByNumber(code) { found ->
                                isSearchingCode = false
                                if (found != null) {
                                    loadTicketToEdit(found)
                                    showSearchCodeDialog = false
                                    Toast.makeText(
                                        context,
                                        Strings.t("ticket_loaded_for_modification", currentLanguage),
                                        Toast.LENGTH_LONG
                                    ).show()
                                } else {
                                    searchCodeError = Strings.t("ticket_not_found", currentLanguage)
                                }
                            }
                        }
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = TopBarPurple),
                    shape = RoundedCornerShape(8.dp),
                    enabled = !isSearchingCode && searchCodeInput.isNotBlank()
                ) {
                    if (isSearchingCode) {
                        CircularProgressIndicator(color = Color.White, strokeWidth = 2.dp, modifier = Modifier.size(16.dp))
                    } else {
                        Icon(Icons.Default.Search, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(modifier = Modifier.width(4.dp))
                        Text(
                            text = Strings.t("modify_or_replay", currentLanguage),
                            color = Color.White,
                            fontWeight = FontWeight.Black
                        )
                    }
                }
            },
            dismissButton = {
                OutlinedButton(
                    onClick = { showSearchCodeDialog = false },
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = Strings.t("close", currentLanguage),
                        color = Color(0xFF616161),
                        fontWeight = FontWeight.Bold
                    )
                }
            }
        )
    }

    // MODAL MOTEUR CENTRAL INTELLIGENT DE GÉNÉRATION & MISES
    if (showCombinationDialog) {
        val currentBoletSources = boletLines
            .filter { it.number.isNotBlank() }
            .map { CombinationEngine.normalizeSourceNumber(it.number) }

        val currentSourceBets = boletLines
            .filter { it.number.isNotBlank() && (it.amount.toDoubleOrNull() ?: 0.0) > 0 }
            .associate { CombinationEngine.normalizeSourceNumber(it.number) to (it.amount.toDoubleOrNull() ?: 0.0) }

        CombinationEngineDialog(
            isOpen = showCombinationDialog,
            onDismiss = { showCombinationDialog = false },
            initialSources = currentBoletSources,
            sourceBetsMap = currentSourceBets,
            openDraws = openDraws,
            selectedDraws = selectedDraws,
            existingGrids = allGrids,
            isCreole = isCreole,
            onApply = { combos, overwrite ->
                applyGeneratedCombinations(combos, overwrite)
                showCombinationDialog = false
            }
        )
    }
}

/**
 * COMPOSABLE DIALOG DU MOTEUR CENTRAL DE COMBINAISONS ET DE MISES
 */
@Composable
fun CombinationEngineDialog(
    isOpen: Boolean,
    onDismiss: () -> Unit,
    initialSources: List<String>,
    sourceBetsMap: Map<String, Double>,
    openDraws: List<OpenDrawItem>,
    selectedDraws: List<OpenDrawItem>,
    existingGrids: List<BetGrid>,
    isCreole: Boolean,
    onApply: (List<GeneratedCombination>, Boolean) -> Unit
) {
    if (!isOpen) return

    var sourcesInput by remember { mutableStateOf(initialSources.joinToString(" ")) }
    var selectedGames by remember { mutableStateOf(setOf(EngineGameType.LOTO4, EngineGameType.MARIAGE)) }
    var betMode by remember { mutableStateOf(BetCalculationMode.UNIT_BET) }
    var unitBetInput by remember { mutableStateOf("10") }
    var distributedBudgetInput by remember { mutableStateOf("100") }
    var sourceBetRule by remember { mutableStateOf(SourceBetRule.MINIMUM) }
    var loto3PrefixInput by remember { mutableStateOf("1") }
    var loto5PrefixInput by remember { mutableStateOf("1") }
    var overwriteDuplicates by remember { mutableStateOf(false) }

    // Extraction et normalisation des numéros sources (préservation des zéros initiaux)
    val cleanSources = remember(sourcesInput) {
        val tokens = sourcesInput.split(Regex("[\\s,;\\-]+")).map { it.trim() }.filter { it.isNotEmpty() }
        CombinationEngine.extractCleanSources(tokens)
    }

    // Liste modifiable de combinaisons
    var combinationsList by remember { mutableStateOf<List<GeneratedCombination>>(emptyList()) }

    // Regénération dès modification des sources, jeux ou préfixes
    LaunchedEffect(cleanSources, selectedGames, loto3PrefixInput, loto5PrefixInput) {
        val config = EngineConfig(
            defaultPrefixLoto3 = loto3PrefixInput.ifBlank { "1" },
            defaultPrefixLoto5 = loto5PrefixInput.ifBlank { "1" }
        )
        combinationsList = CombinationEngine.generateAllFromBolet(
            sources = cleanSources,
            targetGames = selectedGames,
            config = config
        )
    }

    // Recalcul des montants selon le mode sélectionné
    val finalCombinations = remember(combinationsList, betMode, unitBetInput, distributedBudgetInput, sourceBetRule) {
        val budgetOrUnit = when (betMode) {
            BetCalculationMode.UNIT_BET -> unitBetInput.toDoubleOrNull() ?: 10.0
            BetCalculationMode.DISTRIBUTED_BUDGET -> distributedBudgetInput.toDoubleOrNull() ?: 100.0
            BetCalculationMode.SOURCE_BASED -> 10.0
        }
        CombinationEngine.calculateBetAmounts(
            combinations = combinationsList,
            mode = betMode,
            budgetOrUnitAmount = budgetOrUnit,
            sourceBets = sourceBetsMap,
            sourceRule = sourceBetRule
        )
    }

    // Détection des doublons avec les grilles déjà présentes sur la fiche
    val duplicateCount = remember(finalCombinations, existingGrids) {
        finalCombinations.count { combo ->
            existingGrids.any { grid ->
                val gType = (grid.gameType ?: "BORLETTE").uppercase()
                val cType = combo.gameType.apiCode.uppercase()
                (gType == cType || (gType.contains("MAR") && cType.contains("MAR"))) &&
                    grid.numbers.joinToString(if (gType.contains("MAR")) "X" else "") == combo.number.replace("x", "X")
            }
        }
    }

    // Totaux financiers
    val unitSubtotal = finalCombinations.sumOf { it.betAmount }
    val drawMultiplier = selectedDraws.size.coerceAtLeast(1)
    val grandTotal = unitSubtotal * drawMultiplier

    val dialogTextFieldColors = OutlinedTextFieldDefaults.colors(
        focusedTextColor = Color(0xFF0F172A),
        unfocusedTextColor = Color(0xFF0F172A),
        focusedContainerColor = Color.White,
        unfocusedContainerColor = Color.White,
        cursorColor = TopBarPurple,
        focusedBorderColor = TopBarPurple,
        unfocusedBorderColor = Color(0xFF94A3B8),
        focusedLabelColor = TopBarPurple,
        unfocusedLabelColor = Color(0xFF475569),
        focusedPlaceholderColor = Color(0xFF94A3B8),
        unfocusedPlaceholderColor = Color(0xFF94A3B8)
    )

    AlertDialog(
        onDismissRequest = onDismiss,
        containerColor = Color.White,
        shape = RoundedCornerShape(16.dp),
        title = {
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Column {
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                        Text(text = "⚡", fontSize = 18.sp)
                        Text(
                            text = if (isCreole) "MOTEUR KONBINEZON" else "MOTEUR DE COMBINAISONS",
                            color = TopBarPurple,
                            fontSize = 16.sp,
                            fontWeight = FontWeight.Black
                        )
                    }
                    Text(
                        text = if (isCreole) "Jenere Loto 4, Maryaj & kalkile miz otomatik" else "Génération automatique et répartition des mises",
                        color = Color.Gray,
                        fontSize = 11.sp
                    )
                }
                IconButton(onClick = onDismiss, modifier = Modifier.size(28.dp)) {
                    Icon(Icons.Default.Close, contentDescription = "Fèmen", tint = Color.Gray)
                }
            }
        },
        text = {
            LazyColumn(
                modifier = Modifier
                    .fillMaxWidth()
                    .heightIn(max = 500.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                // SECTION 1 : NUMÉROS SOURCES BÒLET
                item {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
                            Text(
                                text = if (isCreole) "1. Nimewo Sous Bòlet (00-99)" else "1. Numéros sources Borlette (00-99)",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1E293B)
                            )
                            OutlinedTextField(
                                value = sourcesInput,
                                onValueChange = { sourcesInput = it },
                                placeholder = { Text("Eg: 02 20 22", fontSize = 12.sp, color = Color(0xFF94A3B8)) },
                                singleLine = true,
                                textStyle = TextStyle(
                                    color = Color(0xFF0F172A),
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Bold
                                ),
                                colors = dialogTextFieldColors,
                                modifier = Modifier.fillMaxWidth(),
                                shape = RoundedCornerShape(8.dp)
                            )
                            if (cleanSources.isNotEmpty()) {
                                Row(
                                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                                    verticalAlignment = Alignment.CenterVertically
                                ) {
                                    Text(
                                        text = if (isCreole) "${cleanSources.size} nimewo valide :" else "${cleanSources.size} numéros valides :",
                                        fontSize = 10.sp,
                                        color = Color.Gray
                                    )
                                    cleanSources.forEach { s ->
                                        Surface(
                                            color = TopBarPurple.copy(alpha = 0.1f),
                                            shape = RoundedCornerShape(4.dp)
                                        ) {
                                            Text(
                                                text = s,
                                                fontSize = 11.sp,
                                                fontWeight = FontWeight.Bold,
                                                color = TopBarPurple,
                                                modifier = Modifier.padding(horizontal = 4.dp, vertical = 1.dp)
                                            )
                                        }
                                    }
                                }
                            } else {
                                Text(
                                    text = if (isCreole) "Tanpri antre omwen 2 nimewo (Egzanp: 02 20 22)" else "Entrez au moins 2 numéros (Ex: 02 20 22)",
                                    fontSize = 11.sp,
                                    color = RoeDanger,
                                    fontWeight = FontWeight.Medium
                                )
                            }
                        }
                    }
                }

                // SECTION 2 : CHOIX DES JEUX CIBLES
                item {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = if (isCreole) "2. Chwazi Jwèt pou Jenere" else "2. Jeux cibles à générer",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1E293B)
                            )
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                // Loto 4 Chip
                                val l4Active = selectedGames.contains(EngineGameType.LOTO4)
                                Surface(
                                    color = if (l4Active) TopBarPurple else Color(0xFFE2E8F0),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier
                                        .weight(1f)
                                        .clickable {
                                            selectedGames = if (l4Active) selectedGames - EngineGameType.LOTO4 else selectedGames + EngineGameType.LOTO4
                                        }
                                ) {
                                    Text(
                                        text = "Loto 4",
                                        color = if (l4Active) Color.White else Color(0xFF334155),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center,
                                        modifier = Modifier.padding(vertical = 6.dp)
                                    )
                                }

                                // Maryaj Chip
                                val mActive = selectedGames.contains(EngineGameType.MARIAGE)
                                Surface(
                                    color = if (mActive) Color(0xFF2563EB) else Color(0xFFE2E8F0),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier
                                        .weight(1f)
                                        .clickable {
                                            selectedGames = if (mActive) selectedGames - EngineGameType.MARIAGE else selectedGames + EngineGameType.MARIAGE
                                        }
                                ) {
                                    Text(
                                        text = "Maryaj",
                                        color = if (mActive) Color.White else Color(0xFF334155),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center,
                                        modifier = Modifier.padding(vertical = 6.dp)
                                    )
                                }

                                // Loto 3 Chip
                                val l3Active = selectedGames.contains(EngineGameType.LOTO3)
                                Surface(
                                    color = if (l3Active) Color(0xFF0D9488) else Color(0xFFE2E8F0),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier
                                        .weight(1f)
                                        .clickable {
                                            selectedGames = if (l3Active) selectedGames - EngineGameType.LOTO3 else selectedGames + EngineGameType.LOTO3
                                        }
                                ) {
                                    Text(
                                        text = "Loto 3",
                                        color = if (l3Active) Color.White else Color(0xFF334155),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center,
                                        modifier = Modifier.padding(vertical = 6.dp)
                                    )
                                }

                                // Loto 5 Chip
                                val l5Active = selectedGames.contains(EngineGameType.LOTO5)
                                Surface(
                                    color = if (l5Active) Color(0xFFD97706) else Color(0xFFE2E8F0),
                                    shape = RoundedCornerShape(8.dp),
                                    modifier = Modifier
                                        .weight(1f)
                                        .clickable {
                                            selectedGames = if (l5Active) selectedGames - EngineGameType.LOTO5 else selectedGames + EngineGameType.LOTO5
                                        }
                                ) {
                                    Text(
                                        text = "Loto 5",
                                        color = if (l5Active) Color.White else Color(0xFF334155),
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        textAlign = TextAlign.Center,
                                        modifier = Modifier.padding(vertical = 6.dp)
                                    )
                                }
                            }

                            // Préfixes si Loto 3 ou Loto 5 sélectionnés
                            if (selectedGames.contains(EngineGameType.LOTO3) || selectedGames.contains(EngineGameType.LOTO5)) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.spacedBy(8.dp)
                                ) {
                                    if (selectedGames.contains(EngineGameType.LOTO3)) {
                                        OutlinedTextField(
                                            value = loto3PrefixInput,
                                            onValueChange = { loto3PrefixInput = it.filter { c -> c.isDigit() }.take(1) },
                                            label = { Text("Prefiks Loto 3", fontSize = 10.sp, color = Color(0xFF475569)) },
                                            singleLine = true,
                                            textStyle = TextStyle(
                                                color = Color(0xFF0F172A),
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.Bold
                                            ),
                                            colors = dialogTextFieldColors,
                                            modifier = Modifier.weight(1f),
                                            shape = RoundedCornerShape(6.dp)
                                        )
                                    }
                                    if (selectedGames.contains(EngineGameType.LOTO5)) {
                                        OutlinedTextField(
                                            value = loto5PrefixInput,
                                            onValueChange = { loto5PrefixInput = it.filter { c -> c.isDigit() }.take(1) },
                                            label = { Text("Prefiks Loto 5", fontSize = 10.sp, color = Color(0xFF475569)) },
                                            singleLine = true,
                                            textStyle = TextStyle(
                                                color = Color(0xFF0F172A),
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.Bold
                                            ),
                                            colors = dialogTextFieldColors,
                                            modifier = Modifier.weight(1f),
                                            shape = RoundedCornerShape(6.dp)
                                        )
                                    }
                                }
                            }
                        }
                    }
                }

                // SECTION 3 : CHOIX DES MISES (3 MODES)
                item {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFF8FAFC)),
                        shape = RoundedCornerShape(10.dp),
                        border = BorderStroke(1.dp, Color(0xFFE2E8F0))
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                            Text(
                                text = if (isCreole) "3. Mòd Kalkil Miz yo" else "3. Mode de calcul des mises",
                                fontSize = 12.sp,
                                fontWeight = FontWeight.Bold,
                                color = Color(0xFF1E293B)
                            )

                            // Mode 1 : Fiks pa Konbinezon
                            Surface(
                                color = if (betMode == BetCalculationMode.UNIT_BET) Color(0xFFEFF6FF) else Color.White,
                                shape = RoundedCornerShape(8.dp),
                                border = BorderStroke(1.dp, if (betMode == BetCalculationMode.UNIT_BET) Color(0xFF2563EB) else Color(0xFFE2E8F0)),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { betMode = BetCalculationMode.UNIT_BET }
                            ) {
                                Column(modifier = Modifier.padding(8.dp)) {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        RadioButton(
                                            selected = betMode == BetCalculationMode.UNIT_BET,
                                            onClick = { betMode = BetCalculationMode.UNIT_BET },
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = if (isCreole) "Mòd 1 : Miz pa Konbinezon (Fiks)" else "Mode 1 : Mise par combinaison (Fixe)",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF0F172A)
                                        )
                                    }
                                    if (betMode == BetCalculationMode.UNIT_BET) {
                                        Spacer(modifier = Modifier.height(4.dp))
                                        OutlinedTextField(
                                            value = unitBetInput,
                                            onValueChange = { unitBetInput = it.filter { c -> c.isDigit() || c == '.' } },
                                            label = { Text(if (isCreole) "Montan pou chak jwèt (HTG)" else "Montant unitaire (HTG)", fontSize = 10.sp, color = Color(0xFF475569)) },
                                            singleLine = true,
                                            textStyle = TextStyle(
                                                color = Color(0xFF0F172A),
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.Bold
                                            ),
                                            colors = dialogTextFieldColors,
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(6.dp)
                                        )
                                        val totalUnitMode = (finalCombinations.size * (unitBetInput.toDoubleOrNull() ?: 0.0))
                                        Text(
                                            text = if (isCreole) "Eg: ${finalCombinations.size} konbinezon x $unitBetInput HTG = ${String.format(java.util.Locale.US, "%.2f", totalUnitMode)} HTG" else "Total = Nbr x Montant",
                                            fontSize = 10.sp,
                                            color = Color.Gray,
                                            modifier = Modifier.padding(top = 2.dp)
                                        )
                                    }
                                }
                            }

                            // Mode 2 : Bidjè Total Distribye
                            Surface(
                                color = if (betMode == BetCalculationMode.DISTRIBUTED_BUDGET) Color(0xFFEFF6FF) else Color.White,
                                shape = RoundedCornerShape(8.dp),
                                border = BorderStroke(1.dp, if (betMode == BetCalculationMode.DISTRIBUTED_BUDGET) Color(0xFF2563EB) else Color(0xFFE2E8F0)),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { betMode = BetCalculationMode.DISTRIBUTED_BUDGET }
                            ) {
                                Column(modifier = Modifier.padding(8.dp)) {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        RadioButton(
                                            selected = betMode == BetCalculationMode.DISTRIBUTED_BUDGET,
                                            onClick = { betMode = BetCalculationMode.DISTRIBUTED_BUDGET },
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = if (isCreole) "Mòd 2 : Bidjè Total Distribye (Egal)" else "Mode 2 : Budget total distribué (Sans perte)",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF0F172A)
                                        )
                                    }
                                    if (betMode == BetCalculationMode.DISTRIBUTED_BUDGET) {
                                        Spacer(modifier = Modifier.height(4.dp))
                                        OutlinedTextField(
                                            value = distributedBudgetInput,
                                            onValueChange = { distributedBudgetInput = it.filter { c -> c.isDigit() || c == '.' } },
                                            label = { Text(if (isCreole) "Bidjè total pou tout konbinezon yo (HTG)" else "Budget global total (HTG)", fontSize = 10.sp, color = Color(0xFF475569)) },
                                            singleLine = true,
                                            textStyle = TextStyle(
                                                color = Color(0xFF0F172A),
                                                fontSize = 14.sp,
                                                fontWeight = FontWeight.Bold
                                            ),
                                            colors = dialogTextFieldColors,
                                            modifier = Modifier.fillMaxWidth(),
                                            shape = RoundedCornerShape(6.dp)
                                        )
                                        Text(
                                            text = if (isCreole) "Bidjè a ap divize san pèdi santim. Sòm tout miz yo egal bidjè a egzakteman." else "Zéro perte de centimes, somme exacte garantie.",
                                            fontSize = 10.sp,
                                            color = Color(0xFF2563EB),
                                            fontWeight = FontWeight.Medium,
                                            modifier = Modifier.padding(top = 2.dp)
                                        )
                                    }
                                }
                            }

                            // Mode 3 : Kalkile sou Nimewo Sous Bòlet
                            Surface(
                                color = if (betMode == BetCalculationMode.SOURCE_BASED) Color(0xFFEFF6FF) else Color.White,
                                shape = RoundedCornerShape(8.dp),
                                border = BorderStroke(1.dp, if (betMode == BetCalculationMode.SOURCE_BASED) Color(0xFF2563EB) else Color(0xFFE2E8F0)),
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .clickable { betMode = BetCalculationMode.SOURCE_BASED }
                            ) {
                                Column(modifier = Modifier.padding(8.dp)) {
                                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                                        RadioButton(
                                            selected = betMode == BetCalculationMode.SOURCE_BASED,
                                            onClick = { betMode = BetCalculationMode.SOURCE_BASED },
                                            modifier = Modifier.size(18.dp)
                                        )
                                        Text(
                                            text = if (isCreole) "Mòd 3 : Kalkile sou Nimewo Sous Bòlet" else "Mode 3 : Calculé d'après les mises Borlette",
                                            fontSize = 11.sp,
                                            fontWeight = FontWeight.Bold,
                                            color = Color(0xFF0F172A)
                                        )
                                    }
                                    if (betMode == BetCalculationMode.SOURCE_BASED) {
                                        Spacer(modifier = Modifier.height(4.dp))
                                        Row(
                                            modifier = Modifier.fillMaxWidth(),
                                            horizontalArrangement = Arrangement.spacedBy(4.dp)
                                        ) {
                                            listOf(
                                                SourceBetRule.MINIMUM to "Minimum",
                                                SourceBetRule.AVERAGE to "Mwayèn",
                                                SourceBetRule.BASE_FIRST to "Premye"
                                            ).forEach { (rule, label) ->
                                                Surface(
                                                    color = if (sourceBetRule == rule) TopBarPurple else Color(0xFFE2E8F0),
                                                    shape = RoundedCornerShape(6.dp),
                                                    modifier = Modifier
                                                        .weight(1f)
                                                        .clickable { sourceBetRule = rule }
                                                ) {
                                                    Text(
                                                        text = label,
                                                        color = if (sourceBetRule == rule) Color.White else Color(0xFF334155),
                                                        fontSize = 10.sp,
                                                        fontWeight = FontWeight.Bold,
                                                        textAlign = TextAlign.Center,
                                                        modifier = Modifier.padding(vertical = 5.dp)
                                                    )
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                // SECTION 4 : ALERTE DOUBLONS (LE CAS ÉCHÉANT)
                if (duplicateCount > 0) {
                    item {
                        Card(
                            colors = CardDefaults.cardColors(containerColor = Color(0xFFFFFBEB)),
                            shape = RoundedCornerShape(8.dp),
                            border = BorderStroke(1.dp, Color(0xFFFDE68A))
                        ) {
                            Column(modifier = Modifier.padding(8.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(4.dp)) {
                                    Text(text = "⚠️", fontSize = 14.sp)
                                    Text(
                                        text = if (isCreole) "$duplicateCount konbinezon egziste deja nan fich la" else "$duplicateCount combinaisons existent déjà dans le ticket",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF92400E)
                                    )
                                }
                                Row(
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(6.dp),
                                    modifier = Modifier.clickable { overwriteDuplicates = !overwriteDuplicates }
                                ) {
                                    Checkbox(
                                        checked = overwriteDuplicates,
                                        onCheckedChange = { overwriteDuplicates = it },
                                        modifier = Modifier.size(20.dp)
                                    )
                                    Text(
                                        text = if (isCreole) "Ekraze / Fisyone montan yo (ranplase ansyen yo)" else "Écraser / Fusionner les montants existants",
                                        fontSize = 10.sp,
                                        color = Color(0xFF92400E),
                                        fontWeight = FontWeight.Medium
                                    )
                                }
                            }
                        }
                    }
                }

                // SECTION 5 : APERÇU DÉTAILLÉ DES COMBINAISONS GÉNÉRÉES
                item {
                    Text(
                        text = if (isCreole) "4. Apèsi Konbinezon (${finalCombinations.size})" else "4. Aperçu des combinaisons (${finalCombinations.size})",
                        fontSize = 12.sp,
                        fontWeight = FontWeight.Bold,
                        color = Color(0xFF1E293B)
                    )
                }

                items(finalCombinations) { combo ->
                    val gameColor = when (combo.gameType) {
                        EngineGameType.LOTO4 -> TopBarPurple
                        EngineGameType.MARIAGE -> Color(0xFF2563EB)
                        EngineGameType.LOTO3 -> Color(0xFF0D9488)
                        EngineGameType.LOTO5 -> Color(0xFFD97706)
                        else -> Color(0xFF64748B)
                    }

                    Surface(
                        color = Color(0xFFF8FAFC),
                        shape = RoundedCornerShape(8.dp),
                        border = BorderStroke(1.dp, Color(0xFFE2E8F0)),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Row(
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(horizontal = 8.dp, vertical = 6.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Surface(
                                    color = gameColor.copy(alpha = 0.15f),
                                    shape = RoundedCornerShape(4.dp)
                                ) {
                                    Text(
                                        text = combo.gameType.displayName,
                                        color = gameColor,
                                        fontSize = 9.sp,
                                        fontWeight = FontWeight.Black,
                                        modifier = Modifier.padding(horizontal = 4.dp, vertical = 2.dp)
                                    )
                                }
                                Text(
                                    text = combo.number,
                                    fontSize = 14.sp,
                                    fontWeight = FontWeight.Black,
                                    fontFamily = FontFamily.Monospace,
                                    color = Color(0xFF0F172A)
                                )
                            }

                            Row(
                                verticalAlignment = Alignment.CenterVertically,
                                horizontalArrangement = Arrangement.spacedBy(6.dp)
                            ) {
                                Text(
                                    text = "${String.format(java.util.Locale.US, "%.2f", combo.betAmount)} HTG",
                                    fontSize = 12.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = TopBarPurple
                                )
                                IconButton(
                                    onClick = {
                                        combinationsList = combinationsList.filter { it.displayKey != combo.displayKey }
                                    },
                                    modifier = Modifier.size(24.dp)
                                ) {
                                    Icon(
                                        imageVector = Icons.Default.Close,
                                        contentDescription = "Efase",
                                        tint = RoeDanger,
                                        modifier = Modifier.size(16.dp)
                                    )
                                }
                            }
                        }
                    }
                }

                // SECTION 6 : RÉCAPITULATIF FINANCIER
                item {
                    Card(
                        colors = CardDefaults.cardColors(containerColor = Color(0xFFEDE9FE)),
                        shape = RoundedCornerShape(10.dp),
                        modifier = Modifier.fillMaxWidth()
                    ) {
                        Column(modifier = Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween
                            ) {
                                Text(
                                    text = if (isCreole) "Total Miz (1 Tiraj) :" else "Sous-total (1 Tirage) :",
                                    fontSize = 11.sp,
                                    color = Color(0xFF5B21B6)
                                )
                                Text(
                                    text = "${String.format(java.util.Locale.US, "%.2f", unitSubtotal)} HTG",
                                    fontSize = 11.sp,
                                    fontWeight = FontWeight.Bold,
                                    color = Color(0xFF5B21B6)
                                )
                            }
                            if (drawMultiplier > 1) {
                                Row(
                                    modifier = Modifier.fillMaxWidth(),
                                    horizontalArrangement = Arrangement.SpaceBetween
                                ) {
                                    Text(
                                        text = if (isCreole) "Miltiplikatè Tiraj :" else "Multiplicateur Tirages :",
                                        fontSize = 11.sp,
                                        color = Color(0xFF5B21B6)
                                    )
                                    Text(
                                        text = "x $drawMultiplier tiraj",
                                        fontSize = 11.sp,
                                        fontWeight = FontWeight.Bold,
                                        color = Color(0xFF5B21B6)
                                    )
                                }
                            }
                            HorizontalDivider(color = Color(0xFFDDD6FE), thickness = 1.dp)
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                horizontalArrangement = Arrangement.SpaceBetween,
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                Text(
                                    text = if (isCreole) "GRAN TOTAL TIKÈ :" else "TOTAL GÉNÉRAL :",
                                    fontSize = 13.sp,
                                    fontWeight = FontWeight.Black,
                                    color = Color(0xFF4C1D95)
                                )
                                Text(
                                    text = "${String.format(java.util.Locale.US, "%.2f", grandTotal)} HTG",
                                    fontSize = 15.sp,
                                    fontWeight = FontWeight.Black,
                                    fontFamily = FontFamily.Monospace,
                                    color = Color(0xFF4C1D95)
                                )
                            }
                        }
                    }
                }
            }
        },
        confirmButton = {
            Button(
                onClick = {
                    onApply(finalCombinations, overwriteDuplicates)
                },
                enabled = finalCombinations.isNotEmpty(),
                colors = ButtonDefaults.buttonColors(containerColor = TopBarPurple),
                shape = RoundedCornerShape(8.dp)
            ) {
                Icon(Icons.Default.Check, contentDescription = null, modifier = Modifier.size(16.dp))
                Spacer(modifier = Modifier.width(4.dp))
                Text(
                    text = if (isCreole) "APLIKE NAN FICH (${finalCombinations.size})" else "APPLIQUER AU TICKET (${finalCombinations.size})",
                    fontSize = 12.sp,
                    fontWeight = FontWeight.Black,
                    color = Color.White
                )
            }
        },
        dismissButton = {
            OutlinedButton(
                onClick = onDismiss,
                shape = RoundedCornerShape(8.dp)
            ) {
                Text(
                    text = if (isCreole) "ANILE" else "ANNULER",
                    fontSize = 12.sp,
                    color = Color(0xFF64748B)
                )
            }
        }
    )
}
